const r=$input.first().json;
const generationEndedAt=Date.now();   // fim da etapa de geração SQL (resposta da LLM recebida)
const text=(r.output??[]).filter(o=>o.type==='message').flatMap(o=>o.content??[]).find(c=>typeof c.text==='string')?.text;
const usage=r.usage??null;            // tokens informados pela API da OpenAI
const llm={model:r.model??null,usage,generationEndedAt};
const resultado=JSON.parse(text);    // comportamento original da arquitetura A: falha se não for JSON
return [{json:{...resultado,...llm}}];

const resultados = $input.all().map(item => item.json);

// Recupera os dados da requisição original
const entrada = $('Preparar entrada').first().json;

// Recupera o SQL gerado pelo GPT
const geracao = $('Extrai sql').first(0).json;

function metricas({startedAt, emb, embeddingUsed, ctx, llmCalled, g}) {
  const u=g?.usage??null;
  const llmInput = llmCalled ? (u?.input_tokens ?? null) : 0;
  const llmOutput = llmCalled ? (u?.output_tokens ?? null) : 0;
  const llmReasoning = llmCalled ? (u?.output_tokens_details?.reasoning_tokens ?? null) : 0;
  const embedding = !embeddingUsed ? 0 : (emb?.embeddingTokens ?? null);
  const parts=[llmInput,llmOutput,embedding];
  const total = parts.some(x=>x===null) ? null : parts.reduce((a,b)=>a+b,0);
  const contextReadyAt = ctx ? ctx.retrievalEndedAt : startedAt;   // A: contexto fixo, pronto no início
  return {
    model: g?.model ?? null,
    usage: u,
    tokens: {llmInput, llmOutput, llmReasoning, embedding, total},
    stageTimingsMs: {
      retrieval: ctx?.retrievalEndedAt ? ctx.retrievalEndedAt - startedAt : null,
      generation: (g?.generationEndedAt && contextReadyAt) ? g.generationEndedAt - contextReadyAt : null,
    },
  };
}
const m = metricas({startedAt: entrada.startedAt, emb: null, embeddingUsed: false, ctx: null, llmCalled: true, g: geracao});

// Identifica as colunas retornadas
const columns = resultados.length > 0
  ? Object.keys(resultados[0])
  : [];

// Transforma os objetos em arrays
const rows = resultados.map(registro =>
  columns.map(coluna => registro[coluna] ?? null)
);

// Calcula o tempo de processamento
const executionTimeMs = Date.now() - entrada.startedAt;

// Monta a resposta para o frontend
const resposta = {
  requestId: entrada.requestId,
  conversationId: entrada.conversationId,
  architecture: "baseline",
  status: "completed",

  message: resultados.length > 0
    ? `Consulta executada com sucesso. ${resultados.length} registro(s) retornado(s).`
    : "Consulta executada com sucesso, mas nenhum registro foi encontrado.",

  data: {
    columns,
    rows
  },

  metadata: {
    executionTimeMs,
    attempts: 1,
    sql: geracao.sql,
    ...m   // model, usage, tokens, stageTimingsMs
  }
};

return [{ json: resposta }];
